import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure proper types
    target_state["order_id"] = target_state["order_id"].astype("int64")
    target_state["last_seq"] = target_state["last_seq"].astype("int64")

    cdc_events["seq"] = cdc_events["seq"].astype("int64")
    cdc_events["order_id"] = cdc_events["order_id"].astype("int64")

    # Step 1: Deduplicate events by seq (keep first occurrence)
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Step 2: Apply replay guard – filter events where seq <= last_seq for existing orders
    # Create a map of order_id -> last_seq from target_state
    last_seq_map = dict(zip(target_state["order_id"], target_state["last_seq"]))

    def passes_replay_guard(row):
        order_id = row["order_id"]
        seq = row["seq"]
        if order_id in last_seq_map:
            return seq > last_seq_map[order_id]
        return True

    cdc_events = cdc_events[cdc_events.apply(passes_replay_guard, axis=1)].copy()

    # Step 3: Sort by seq to apply in order
    cdc_events = cdc_events.sort_values("seq").reset_index(drop=True)

    # Step 4: Track order state as we apply events
    # Build state dict from target_state
    state = {}
    for _, row in target_state.iterrows():
        order_id = row["order_id"]
        state[order_id] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"]
        }

    # Track which orders have been touched and their last operation
    last_op = {}  # order_id -> (op, seq)

    for _, event in cdc_events.iterrows():
        order_id = event["order_id"]
        seq = event["seq"]
        op = event["op"]

        if op == "I" or op == "U":
            if order_id not in state:
                # Create new row
                state[order_id] = {
                    "status": event["status"],
                    "amount": event["amount"],
                    "last_seq": seq
                }
            else:
                # Update existing row
                state[order_id]["status"] = event["status"]
                # For 'U', only update amount if it's not NULL
                if op == "U":
                    if pd.notna(event["amount"]):
                        state[order_id]["amount"] = event["amount"]
                else:  # op == "I"
                    state[order_id]["amount"] = event["amount"]
                state[order_id]["last_seq"] = seq
            last_op[order_id] = (op, seq)
        elif op == "D":
            if order_id in state:
                del state[order_id]
            last_op[order_id] = (op, seq)

    # Step 5: Build new_state
    new_state_rows = []
    for order_id, order_data in state.items():
        new_state_rows.append({
            "order_id": order_id,
            "status": order_data["status"],
            "amount": order_data["amount"],
            "last_seq": order_data["last_seq"]
        })

    new_state = pd.DataFrame(new_state_rows, columns=["order_id", "status", "amount", "last_seq"])
    if len(new_state) == 0:
        new_state = pd.DataFrame(columns=["order_id", "status", "amount", "last_seq"])
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
    else:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")

    # Step 6: Build tombstones – orders with last applied event being 'D'
    tombstone_rows = []
    for order_id, (op, seq) in last_op.items():
        if op == "D":
            tombstone_rows.append({
                "order_id": order_id,
                "deleted_seq": seq
            })

    tombstones = pd.DataFrame(tombstone_rows, columns=["order_id", "deleted_seq"])
    if len(tombstones) == 0:
        tombstones = pd.DataFrame(columns=["order_id", "deleted_seq"])
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")

    return {
        "new_state": new_state,
        "tombstones": tombstones
    }
